import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxSelect,
  JxButton,
  JxDivider,
} from '@jinx-ui/react';

type RegistrationData = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  comment: string;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationData) => void;
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
];

const emptyData: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  comment: '',
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(emptyData);

  const update = <K extends keyof RegistrationData>(key: K, value: RegistrationData[K]) => {
    setData((prev) => ({ ...prev, [key]: value }));
  };

  const contactsFilled = data.name.trim() !== '' && data.email.trim() !== '';
  const addressFilled = data.country !== '' && data.city.trim() !== '';
  const canGoNext = step === 0 ? contactsFilled : step === 1 ? addressFilled : true;

  const countryLabel = countries.find((item) => item.value === data.country)?.label ?? '—';

  return (
    <div style={{ display: 'grid', gap: '24px', fontFamily: 'var(--jx-font-sans)' }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            placeholder="Иван Иванов"
            onChange={(event) => update('name', event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            placeholder="ivan@example.com"
            onChange={(event) => update('email', event.target.value)}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={data.phone}
            helperText="Необязательно"
            onChange={(event) => update('phone', event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={countries}
            value={data.country}
            onValueChange={(value) => update('country', value)}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={(event) => update('city', event.target.value)}
          />
          <JxInputField
            label="Улица и дом"
            value={data.street}
            onChange={(event) => update('street', event.target.value)}
          />
          <JxTextareaField
            label="Комментарий к адресу"
            rows={3}
            maxLength={300}
            value={data.comment}
            onChange={(event) => update('comment', event.target.value)}
            helperText={`${data.comment.length}/300`}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxDivider label="Контакты" />
          <div style={{ display: 'grid', gap: '6px', color: 'var(--jx-text-2)' }}>
            <span>Имя: {data.name || '—'}</span>
            <span>Почта: {data.email || '—'}</span>
            <span>Телефон: {data.phone ? `+7${data.phone}` : '—'}</span>
          </div>
          <JxDivider label="Адрес" />
          <div style={{ display: 'grid', gap: '6px', color: 'var(--jx-text-2)' }}>
            <span>Страна: {countryLabel}</span>
            <span>Город: {data.city || '—'}</span>
            <span>Улица и дом: {data.street || '—'}</span>
            <span>Комментарий: {data.comment || '—'}</span>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={() => setStep(step - 1)}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" disabled={!canGoNext} onClick={() => setStep(step + 1)}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={() => onSubmit(data)}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

